#!/usr/bin/env bash
set -euo pipefail
ROOT="$(cd "$(dirname "$0")/../.." && pwd)"; BIN=${BIN:-$ROOT/build-cutest/lazyipdca_cutest}; MANIFEST=${MANIFEST:-$ROOT/benchmarks/manifests/cutest37.csv}; OUT=${OUT:-$ROOT/results/runs/sensitivity_rho10_$(date +%Y%m%d_%H%M%S)}; mkdir -p "$OUT"; export OMP_NUM_THREADS=1 OPENBLAS_NUM_THREADS=1 MKL_NUM_THREADS=1 BLIS_NUM_THREADS=1 NUMEXPR_NUM_THREADS=1
CASES=(NCVXQP1_n1000 BLOWEYA_n2002 STNQP1_n8193 BLOCKQP3_n10010 NCVXQP3_n10000 QPNBOEI1_n384 QPNSTAIR_n385 NCVXBQP3_n10000 NCVXQP6_n1000 QPNBAND_n50000)
COMMON=(--manifest "$MANIFEST" --init 2 --backend ldl --regularization-mode lazy --rho-init auto --rho-init-rel-margin 1e-6 --rho-init-abs-margin 1e-8 --rho-decay 0.5 --reject-streak-rho-bump 50 --rho-dyn-reject-growth 2.0 --rho-dyn-floor-rel-margin 1e-6 --max-atoms 500 --adaptive-atoms --atom-oracle --atom-cluster --adaptive-marginal-return --atom-events --atom-event-every 50 --bound-push 0 --bp-push-kappa 1e-4 --bp-margin-tol 1e-4 --bp-adaptive --escapes 3 --mehrotra --sigma-max 1e14 --model-solved-tol 1e-12 --dca-stop --dca-stall-tol-rel 1e-10 --dca-stall-iters 5 --dca-monotone-tol-abs 1e-6 --lanczos-maxit 60 --rho-lanczos-residual-safety 1.0 --atom-oracle-activity-weight 0.5 --atom-oracle-directional-weight 0.5 --atom-oracle-beta-weight 0.05 --atom-oracle-coupling-weight 0.1 --atom-oracle-density-weight 0.1 --max-iter 3000 --time-limit 36000 --eps 1e-6)
for rho in 1 2 5; do for tag in "${CASES[@]}"; do "$BIN" "${COMMON[@]}" --rho-trial-every "$rho" --problem "$tag" --outdir "$OUT/rho${rho}/$tag" > "$OUT/rho${rho}_${tag}.log" 2>&1 || true; done; done; echo "$OUT"
